mapper.select:
/* selectMasterMdctBuyerReportManageList */ SELECT A.REPORT_NO , A.GROUP_CODE , A.GROUP_NAME , 1 AS PRINT_IMG , A.CLOSE_MONTH , TO_CHAR(ADD_MONTHS(TO_DATE(A.CLOSE_MONTH, 'YYYYMM'), -1), 'YYYYMM') AS CLOSE_MONTH_M1 , TO_CHAR(ADD_MONTHS(TO_DATE(A.CLOSE_MONTH, 'YYYYMM'), -12), 'YYYYMM') AS CLOSE_MONTH_M12 , A.STATUS , A.TR_YN , A.TR_TYPE , A.TR_STATUS , A.TRDT_YN , A.TRDT_TYPE , A.TRDT_STATUS , A.CONTRACT_YN , A.CONTRACT_TYPE , A.CONTRACT_STATUS , A.RD_YN , A.RD_TYPE , A.RD_STATUS , A.BUYER_CA_RD_YN , A.BUYER_CA_RD_TYPE , A.BUYER_CA_RD_STATUS , A.PD_YN , A.PD_TYPE , A.PD_STATUS , A.BUYER_CA_PD_YN , A.BUYER_CA_PD_TYPE , A.BUYER_CA_PD_STATUS , A.DE_CD_YN , A.DE_CD_TYPE , A.DE_CD_STATUS , A.DE_WD_YN , A.DE_WD_TYPE , A.DE_WD_STATUS , A.RE_CD_YN , A.RE_CD_TYPE , A.RE_CD_STATUS , A.RE_WD_YN , A.RE_WD_TYPE , A.RE_WD_STATUS , A.EVALUATION_YN , A.EVALUATION_STATUS , A.BUYER_INFO , A.PRINT_DATE , A.ADD_DATE , A.ADD_USER_ID , A.CHANGE_DATE , A.CHANGE_USER_ID , A.CANCEL_NOTE , (SELECT COUNT(B.COM_CODE) FROM ICOMCOD2 A, ICOMCMPY B WHERE A.COMPANY_CODE = 'KRKORE0001' AND A.TYPE ='RPMP' AND A.CODE = B.COM_CODE AND B.STATUS != 'D' AND A.TEXT1 = A.GROUP_CODE AND A.FLAG = 'Y') AS GROUP_CODE_CNT FROM KEP.KEP_REPORT_DT A WHERE A.CLOSE_MONTH BETWEEN #{st_from_date} AND #{st_to_date} AND A.STATUS != 'D' AND A.GROUP_CODE IN (SELECT COD.TEXT1 FROM ICOMCOD2 COD WHERE COD.TYPE ='RPMP' AND COD.FLAG = 'Y' AND COD.CODE IN (SELECT COD.CODE FROM ICOMCOD3 COD3 WHERE COD3.BUYER = 'KRKORE0001' AND COD3.TYPE = 'CMPY' AND COD3.CODE1= 'ALL' AND COD3.CODE2 = #{st_user_id} UNION ALL SELECT MNG.BUYER FROM ICOMCOD3 COD3, MIS_BUYER_MNG MNG WHERE COD3.BUYER = 'KRKORE0001' AND COD3.TYPE = 'CMPY' AND COD3.CODE1= MNG.KEP_DEPT AND COD3.CODE2 = #{st_user_id} AND MNG.YEAR = TO_CHAR(SYSDATE,'YYYY') AND MNG.STATUS = 'C' UNION ALL SELECT BUYER FROM MIS_BUYER_MNG WHERE YEAR = TO_CHAR(SYSDATE,'YYYY') AND STATUS = 'C' AND KEP_USER_ID = #{st_user_id} UNION ALL SELECT COD.CODE1 FROM ICOMCOD3 COD , ICOMCMPY CMPY WHERE COD.BUYER = 'KRKORE0001' AND COD.TYPE = 'CMPY' AND COD.CODE1 = CMPY.COM_CODE AND COD.CODE2 = #{st_user_id} AND TO_CHAR(SYSDATE,'YYYYMMDD') BETWEEN TEXT2 AND TEXT3 ) )
AND A.GROUP_CODE LIKE '%'||#{st_group_code}||'%'
AND A.GROUP_NAME LIKE '%'||#{st_group_nm}||'%'
AND A.STATUS = #{st_contract_status}
ORDER BY A.GROUP_CODE, A.CLOSE_MONTH

mapper.update:

/*deleteMasterMdctBuyerReportReportDt*/
UPDATE KEP_REPORT_DT					
   SET STATUS      = 'D' 	
     , CHANGE_DATE = SYSDATE
     , CHANGE_USER_ID = #{st_user_id}	
     , CANCEL_NOTE = '재생성으로 인한 기존 데이터 삭제'
 WHERE REPORT_NO = #{REPORT_NO}
